// under `mise run test`; explore with
// go test -fuzz=FuzzFitSpansTheColumn -fuzztime=60s ./internal/ui/datatable
func FuzzFitSpansTheColumn(f *testing.F) {
	for _, tc := range agreedWidths {
		f.Add(tc.s)
