		"\\u20E3x",   // a stray keycap mark
	} {
		f.Add(s)
	}
	f.Fuzz(func(t *testing.T, s string) {
		if !utf8.ValidString(s) {
			t.Skip("invalid UTF-8")
		}
		for _, r := range s {
			if unicode.IsControl(r) {
				t.Skip("control characters go through lipgloss and are out of scope")
			}
