		for w := 1; w <= 40; w++ {
			for _, head := range []bool{false, true} {
				if got := ansi.StringWidth(fit(s, w, head)); got != w {
					t.Fatalf("fit(%q, %d, head=%t) = %q: %d cells, want %d", s, w, head, fit(s, w, head), got, w)
